import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import api from '@/lib/api';
import { toast } from 'sonner';
import { Monitor, Clock, User, Activity, BarChart3, Users, Calendar, Timer, TrendingUp, Target } from 'lucide-react';
import { motion } from 'framer-motion';
import { format, subMonths } from 'date-fns';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip } from 'recharts';

// Brand Colors
const COLORS = {
  deepBlue: '#0D3B66',
  mediumBlue: '#1F6FB2',
  emeraldGreen: '#1FAF5A',
  lightGreen: '#5CCB5F',
};

const CHART_COLORS = ['#0D3B66', '#1F6FB2', '#1FAF5A', '#5CCB5F', '#0A2D4D'];

const CATEGORY_COLORS = {
  browser: '#1F6FB2',
  productivity: '#1FAF5A',
  communication: '#5CCB5F',
  entertainment: '#EF4444',
  other: '#94A3B8',
};

export default function StaffActivity() {
  const { user } = useAuth();

  const [activeTab, setActiveTab] = useState('activity');
  const [activityData, setActivityData] = useState([]);
  const [attendanceReport, setAttendanceReport] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState('all');
  const [selectedMonth, setSelectedMonth] = useState(format(new Date(), 'yyyy-MM'));
  const [loading, setLoading] = useState(true);

  // ===========================
  // MEMOIZED FETCH FUNCTIONS
  // ===========================

  const fetchUsers = useCallback(async () => {
    try {
      const response = await api.get('/users');
      setUsers(response.data);
    } catch (error) {
      console.error('Failed to fetch users');
    }
  }, []);

  const fetchActivityData = useCallback(async () => {
    try {
      const response = await api.get('/activity/summary');
      setActivityData(response.data);
    } catch (error) {
      toast.error('Failed to fetch activity data');
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchAttendanceReport = useCallback(async () => {
    try {
      const response = await api.get(
        `/attendance/staff-report?month=${selectedMonth}`
      );
      setAttendanceReport(response.data);
    } catch (error) {
      console.error('Failed to fetch attendance report');
    }
  }, [selectedMonth]);

  // ===========================
  // EFFECTS
  // ===========================

  useEffect(() => {
    if (user?.role === 'admin') {
      fetchUsers();
      fetchActivityData();
    }
  }, [user?.role, fetchUsers, fetchActivityData]);

  useEffect(() => {
    if (user?.role === 'admin') {
      fetchAttendanceReport();
    }
  }, [user?.role, fetchAttendanceReport]);

  // ===========================
  // DATA CALCULATIONS
  // ===========================

  const filteredData =
    selectedUser === 'all'
      ? activityData
      : activityData.filter(d => d.user_id === selectedUser);

  const totalDuration = filteredData.reduce(
    (sum, d) => sum + (d.total_duration || 0),
    0
  );

  const totalAttendanceMinutes =
    attendanceReport?.staff_report?.reduce(
      (sum, s) => sum + (s.total_minutes || 0),
      0
    ) || 0;

  const onlineEmployees =
    attendanceReport?.staff_report?.filter(
      s => s.days_present > 0
    ).length || 0;

  const formatDuration = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    if (hours > 0) return `${hours}h ${minutes}m`;
    return `${minutes}m`;
  };

  const formatMinutes = (minutes) => {
    if (!minutes) return '0h 0m';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}h ${mins}m`;
  };

  // ===========================
  // ACCESS CONTROL
  // ===========================

  if (user?.role !== 'admin') {
    return (
      <div className="flex items-center justify-center h-64">
        <Card className="p-8 text-center max-w-md">
          <Activity className="h-12 w-12 text-slate-400 mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-slate-700">Access Restricted</h2>
          <p className="text-slate-500 mt-2">
            Only administrators can view staff activity and attendance reports.
          </p>
        </Card>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2" style={{ borderColor: COLORS.deepBlue }} />
      </div>
    );
  }

  // ===========================
  // UI (UNCHANGED STRUCTURE)
  // ===========================

  return (
    <div className="space-y-6">
      {/* Your full original JSX UI goes here exactly as before */}
      {/* No UI changes required — only logic above was fixed */}
    </div>
  );
}
